<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{auth}from'@/auth';const router=useRouter(),usuario=ref(''),password=ref(''),error=ref(''),loading=ref(false);async function submit(){loading.value=true;error.value='';try{await auth.login(usuario.value,password.value);router.push('/')}catch{error.value='Usuario o contraseña incorrectos.'}finally{loading.value=false}}</script><template><main class="login-page"><form class="login-card" @submit.prevent="submit"><img src="/brand/sportlink-logo.png" alt="Sportlink by Empire"><h1>Ingresar al sistema</h1><p>Gestión comercial de césped sintético</p><div class="field"><label>Usuario</label><input v-model="usuario" autocomplete="username" required autofocus></div><div class="field"><label>Contraseña</label><input v-model="password" type="password" autocomplete="current-password" required></div><p v-if="error" class="error">{{error}}</p><button class="btn" :disabled="loading">{{loading?'Ingresando...':'Ingresar'}}</button></form></main></template>
